local lfs = require("lfs")
local conn = mapper("ubus").connect()
if lfs.attributes("/etc/config/mmpbx", "mode") ~= "file" then
  return
end

local match, sort = string.match, table.sort
local tostring, tonumber = tostring, tonumber
local uci_helper = mapper("ucihelper")

local InternetGatewayDevice_Services_VoiceService_i_PhyInterface_i_ = {
    objectType = {
        name = "InternetGatewayDevice.Services.VoiceService.{i}.PhyInterface.{i}.",
        access = "readOnly",
        minEntries = 0,
        maxEntries = math.huge,
        parameters = {
            PhyPort = {
                access = "readOnly",
                type = "string",
                max = "2",
            },
            InterfaceID = {
                access = "readOnly",
                type = "unsignedInt",
                range = {
                    {
                        min = "1",
                    },
                },
            },
            Description = {
                access = "readOnly",
                type = "string",
                max = "32",
            },
        }
    }
}

local binding = { config = "mmpbx" }
local descriptionbinding = { option = "user_friendly_name" }
local numOfFxs, numOfDect = 0, 0
local entriesInfo

InternetGatewayDevice_Services_VoiceService_i_PhyInterface_i_.entries = function(mapping, parentkey)
    if not entriesInfo then
        entriesInfo = {SIPUA = {}, INTUA = {}}
        binding.sectionname = "device"
        uci_helper.foreach_on_uci(binding, function(s)
            local entries = entriesInfo["SIPUA"]
            entries[#entries + 1] = s['.name']
            if s['.name']:sub(1,1) == "f" then
                numOfFxs = numOfFxs + 1
            end
            if s['.name']:sub(1,1) == "d" then
                numOfDect = numOfDect + 1
            end
        end)
        sort(entriesInfo["SIPUA"], function(a,b)
            local a1, b1 = a:sub(1,1), b:sub(1,1)
            if (a1 == "f" and ((a1 == b1 and a < b) or a1 ~= b1)) or (a1 ~= "f" and b1 ~= "f" and a < b) then
                return true
            else
                return false
            end
        end)
    end
    return entriesInfo[parentkey]
end

local function getID(mapping, paramname, key)
    local id = match(key, "(%d+)$")
    if key:sub(1,1) == "d" then
        id = tostring(tonumber(id) + numOfFxs)
    end
    if key:sub(1,1) == "s" then
        id = tostring(tonumber(id) + numOfFxs + numOfDect)
    end
    return id
end

InternetGatewayDevice_Services_VoiceService_i_PhyInterface_i_.get = {
    PhyPort = getID,
    InterfaceID = getID,
    Description = function (mapping, paramname, key)
        local res = ""
        binding.sectionname = key
        binding.option = "config"
        local config = uci_helper.get_from_uci(binding)
        if config ~= "" then
            descriptionbinding.config = config
            descriptionbinding.sectionname = key
            res = uci_helper.get_from_uci(descriptionbinding)
        end
        return res
    end
}
register(InternetGatewayDevice_Services_VoiceService_i_PhyInterface_i_)

local InternetGatewayDevice_Services_VoiceService_i_PhyInterface_i_Tests_ = {
    objectType = {
        name = "InternetGatewayDevice.Services.VoiceService.{i}.PhyInterface.{i}.Tests.",
        access = "readOnly",
        minEntries = 1,
        maxEntries = 1,
        parameters = {
            PhoneConnectivity = {
                access = "readOnly",
                type = "boolean",
            },
            TestState = {
                access = "readWrite",
                type = "string",
                enumeration = {
                    "None",
                    "Requested",
                    "Complete",
                    "Error_TestNotSupported",
                },
            },
            TestSelector = {
                access = "readWrite",
                type = "string",
                enumeration = {
                    "PhoneConnectivityTest",
                },
                max = "64",
            },
        }
    }
}

local TestStateMap = {
  ["None"] = "None",
  ["Requested"] = "Requested",
  ["Complete"] = "Complete",
  ["Failure"] = "Error_TestNotSupported",
}
local PhoneConnectivityMap = {
  ["true"] = "1",
  ["false"] = "0",
}

local function getTests(mapping, param, key)
    local test = conn:call("mmbrcmfxs.debug.slic.test", "get", {["device"]=key,["cmdparms"]="PhoneConnectivityTest"})
    if test then
        local val = test[param]
        if param == "TestState" then
            return TestStateMap[val] or ""
        elseif param  == "TestSelector" then
            return "PhoneConnectivityTest"
        else
            return PhoneConnectivityMap[val] or "0"
        end
    end
    return ""
end

InternetGatewayDevice_Services_VoiceService_i_PhyInterface_i_Tests_.get = getTests
InternetGatewayDevice_Services_VoiceService_i_PhyInterface_i_Tests_.set = {
    TestState = function (mapping, param, value, key)
        if (value == "Requested") then
            conn:call("mmbrcmfxs.debug.slic.test", "set", {["device"]=key,["cmdparms"]="PhoneConnectivityTest"})
        else
            return nil, "not supported"
        end
    end,
    TestSelector = function (mapping, param, value, key)
        if (value ~= "PhoneConnectivityTest") then
            return nil, "not supported"
        end
    end
}
register(InternetGatewayDevice_Services_VoiceService_i_PhyInterface_i_Tests_)
